package com.aoo.bcg.common.cache;
import java.time.Duration;import java.util.List;import java.util.Set;
public record RedisLuaContract(String name,int keyCount,boolean sameSlotRequired,Duration timeout,ResultType resultType,Set<String>allowedPrefixes){public enum ResultType{INTEGER,STRING,ARRAY}public RedisLuaContract{if(name==null||name.isBlank()||keyCount<=0||timeout==null||timeout.isNegative()||timeout.isZero()||resultType==null||allowedPrefixes==null||allowedPrefixes.isEmpty())throw new IllegalArgumentException("incomplete Lua contract");allowedPrefixes=Set.copyOf(allowedPrefixes);}public void validate(List<String>keys){if(keys.size()!=keyCount)throw new IllegalArgumentException("Lua key count mismatch");if(keys.stream().anyMatch(key->allowedPrefixes.stream().noneMatch(key::startsWith)))throw new SecurityException("Lua key outside Aoo namespace");if(sameSlotRequired){String tag=tag(keys.getFirst());if(tag==null||keys.stream().anyMatch(key->!tag.equals(tag(key))))throw new IllegalArgumentException("Lua keys cross Redis slots");}}private static String tag(String key){int start=key.indexOf('{'),end=start<0?-1:key.indexOf('}',start+1);return start>=0&&end>start+1?key.substring(start+1,end):null;}}
